export const SELLER_PRICING_BANDS = {
  "Market-aligned": {
    color: "text-emerald-400",
    bg: "bg-emerald-500/10",
    border: "border-emerald-500/40",
    description: "Observed listings are generally close to the current item benchmarks.",
  },
  "Mixed pricing": {
    color: "text-sky-400",
    bg: "bg-sky-500/10",
    border: "border-sky-500/40",
    description: "Observed listings vary between market-aligned and above-range prices.",
  },
  "Frequently above range": {
    color: "text-amber-400",
    bg: "bg-amber-500/10",
    border: "border-amber-500/40",
    description: "A notable share of observed listings sit above the current item ranges.",
  },
  "Strongly above range": {
    color: "text-orange-400",
    bg: "bg-orange-500/10",
    border: "border-orange-500/40",
    description: "Observed listings are often well above the current item ranges.",
  },
};

const LEGACY_LABELS = {
  Trustworthy: "Market-aligned",
  Neutral: "Mixed pricing",
  Suspicious: "Frequently above range",
  Flagged: "Strongly above range",
};

export function sellerPricingBand(label, legacyAutoFlagged = false) {
  if (legacyAutoFlagged) return "Strongly above range";
  if (SELLER_PRICING_BANDS[label]) return label;
  return LEGACY_LABELS[label] || "Mixed pricing";
}

export function sellerPricingDescription(label) {
  return SELLER_PRICING_BANDS[sellerPricingBand(label)].description;
}

export function sellerPricingMeta(label) {
  const normalized = sellerPricingBand(label);
  return { label: normalized, ...SELLER_PRICING_BANDS[normalized] };
}
