import { useEffect } from "react";

// Shared scroll lock for overlays (drawer, palette, sheets, mobile menu).
// Stack-safe: multiple overlays can hold the lock at once; the page
// unlocks only when the last one releases. Locks both <html> and <body>,
// preserves scrollbar width to avoid layout shift, and disables
// overscroll chaining behind the overlay (iOS rubber-banding).
let lockCount = 0;
let saved = null;

function scrollbarWidth() {
  if (typeof window === "undefined" || typeof document === "undefined") return 0;
  return Math.max(0, window.innerWidth - document.documentElement.clientWidth);
}

function applyLock() {
  const html = document.documentElement;
  const body = document.body;
  if (!html || !body) return;
  if (lockCount === 0) {
    const width = scrollbarWidth();
    saved = {
      htmlOverflow: html.style.overflow,
      bodyOverflow: body.style.overflow,
      htmlOverscroll: html.style.overscrollBehavior,
      bodyOverscroll: body.style.overscrollBehavior,
      bodyPaddingRight: body.style.paddingRight,
      htmlGutter: html.style.scrollbarGutter,
    };
    if (width > 0) {
      const current = parseFloat(getComputedStyle(body).paddingRight) || 0;
      body.style.paddingRight = `${current + width}px`;
    }
    html.style.overflow = "hidden";
    body.style.overflow = "hidden";
    html.style.overscrollBehavior = "none";
    body.style.overscrollBehavior = "none";
    html.style.scrollbarGutter = "stable";
  }
  lockCount += 1;
}

function releaseLock() {
  if (lockCount === 0) return;
  lockCount -= 1;
  if (lockCount > 0) return;
  const html = document.documentElement;
  const body = document.body;
  if (saved) {
    if (html) {
      html.style.overflow = saved.htmlOverflow;
      html.style.overscrollBehavior = saved.htmlOverscroll;
      html.style.scrollbarGutter = saved.htmlGutter;
    }
    if (body) {
      body.style.overflow = saved.bodyOverflow;
      body.style.overscrollBehavior = saved.bodyOverscroll;
      body.style.paddingRight = saved.bodyPaddingRight;
    }
    saved = null;
  }
}

export default function useScrollLock(active) {
  useEffect(() => {
    if (!active) return undefined;
    if (typeof document === "undefined") return undefined;
    applyLock();
    return () => releaseLock();
  }, [active]);
}
