export function shopLocationKey(shop) {
  return JSON.stringify([shop.serverKey, shop.dimensionKey, shop.x, shop.y, shop.z, shop.signFingerprint || ""]);
}

export function parseShopLocation(value) {
  try {
    const parts = JSON.parse(value);
    if (!Array.isArray(parts) || parts.length !== 6) return null;
    const [serverKey, dimensionKey, x, y, z, signFingerprint] = parts;
    if (![serverKey, dimensionKey].every(s => typeof s === "string" && s.length > 0 && s.length <= 160)
      || ![x, y, z].every(Number.isSafeInteger) || typeof signFingerprint !== "string" || signFingerprint.length > 128) return null;
    return { serverKey, dimensionKey, x, y, z, signFingerprint };
  } catch { return null; }
}

export function sameShopPosition(a, b) {
  return a.serverKey === b.serverKey && a.dimensionKey === b.dimensionKey
    && a.x === b.x && a.y === b.y && a.z === b.z;
}

export function nearbyShops(shops, center, radius = 64) {
  return shops.filter(shop => shop.serverKey === center.serverKey && shop.dimensionKey === center.dimensionKey
    && Math.hypot(shop.x - center.x, shop.z - center.z) <= radius);
}

export function exactCoins(value) {
  return Number.isFinite(value) ? value.toLocaleString(undefined, { maximumFractionDigits: 8 }) : "Unknown";
}
